      ctx.beginPath();
      ctx.moveTo(i * HUCRE_BOYU, 0);
      ctx.lineTo(i * HUCRE_BOYU, canvas.height);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, i * HUCRE_BOYU);
      ctx.lineTo(canvas.width, i * HUCRE_BOYU);
      ctx.stroke();
